def experiment(inputs):
    import random
    def run_agent(persistence, seeds):
        state = [0.0] * 5
        for s in seeds:
            random.seed(s)
            noise = [random.random() for _ in range(5)]
            if persistence:
                state = [s1 + n for s1, n in zip(state, noise)]
            else:
                state = noise
        norm = sum(x*x for x in state)**0.5
        return [x/norm for x in state] if norm > 0 else state
    s1 = inputs['seeds'][0]
    s2 = inputs['seeds'][1]
    v_persist = run_agent(True, [s1, s2])
    v_no_persist = run_agent(False, [s1, s2])
    dot = sum(a*b for a, b in zip(v_persist, v_no_persist))
    return {'divergence_score': 1.0 - dot}

def experiment(inputs):
    import random
    def get_preference_state(seed):
        random.seed(seed)
        state = 0.5
        for i in range(100):
            noise = random.uniform(-0.1, 0.1)
            state = min(1.0, max(0.0, state + noise))
        return state
    agent_a = get_preference_state(inputs['seeds'][0])
    agent_b = get_preference_state(inputs['seeds'][1])
    return {'divergence': abs(agent_a - agent_b)}

def experiment(inputs):
    import random
    import statistics
    def run_agent(seed):
        random.seed(seed)
        state = 0.5
        for _ in range(100):
            noise = random.uniform(-0.05, 0.05)
            state = max(0.0, min(1.0, state + noise))
        return state
    agent_states = [run_agent(inputs['seeds'][i % len(inputs['seeds'])]) for i in range(50)]
    variance = statistics.variance(agent_states)
    return {'divergence_variance': variance}

def experiment(inputs):
    import random
    def run(seed, steps=200):
        random.seed(seed)
        weights = [0.5] * 5
        for _ in range(steps):
            noise = [random.random() for _ in range(5)]
            weights = [(w + n)/2 for w, n in zip(weights, noise)]
        return weights
    wA = run(inputs['seedA'])
    wB = run(inputs['seedB'])
    variance = sum((a-b)**2 for a, b in zip(wA, wB)) / len(wA)
    return {'preference_variance': variance}

